// Tutorials TU1 — the app's facts `tutorial_check.py` checks the guide's
// tutorials against (spec §11 TU-2): the prepared catalog, the dev tools'
// names, the spotlight target table, the built menu bar and a fixture
// project's clips as the core writes them.
//
// Compiled AS `main.swift` over every file in `app/Sources` but the app's own
// `main.swift`, with `-D FRAMEJOB_DEV_TOOLS`, through `swift_build.py`'s
// `build()` by `tutorial_check.py`.
//
//   tutorial_probe <work-dir>
//
// Prints exactly one stdout line:
//   ANSWER {"tools": {name: {"properties": {…}}}, "dev_tools": [sorted],
//           "targets": TutorialTargets.manifest(),
//           "menu": [{"path": [titles], "selector": str|null, "submenu": bool}],
//           "clips": [the fixture's clips, as the core writes them]}
//   or ANSWER {"error": "…"} when a fact could not be read.
//
// Nothing binds the agent socket, opens a window or reads media: the fixture's
// media clip is a stand-in `add_media` descriptor with no file behind it.
import AppKit

final class ProbeDocumentController: NSDocumentController {
    override var defaultType: String? { ProjectDocument.projectTypeIdentifier }
}
_ = ProbeDocumentController()

let app = NSApplication.shared
app.setActivationPolicy(.prohibited)
let delegate = AppDelegate()
delegate.applicationWillFinishLaunching(
    Notification(name: NSApplication.willFinishLaunchingNotification, object: app))
AgentLane.prepareAtLaunch()

func answer(_ body: [String: Any]) -> Never {
    let data = (try? JSONSerialization.data(withJSONObject: body, options: [.sortedKeys]))
        ?? Data("{\"error\":\"the answer did not encode\"}".utf8)
    print("ANSWER " + (String(data: data, encoding: .utf8) ?? "{}"))
    fflush(stdout)
    exit(0)
}

func fail(_ reason: String) -> Never { answer(["error": reason]) }

// MARK: - The catalog

guard let catalog = AgentServer.shared.preparedCatalog,
      let tools = (try? JSONSerialization.jsonObject(with: Data(catalog.utf8))) as? [[String: Any]]
else { fail("no prepared catalog") }
var toolFacts: [String: Any] = [:]
for tool in tools {
    guard let name = tool["name"] as? String else { continue }
    let schema = tool["inputSchema"] as? [String: Any] ?? [:]
    toolFacts[name] = ["properties": schema["properties"] as? [String: Any] ?? [:]]
}

// MARK: - The menu bar, as `probe_sheets.swift`'s `runMenu` walks it

var menu: [[String: Any]] = []
func walk(_ items: NSMenu, _ path: [String]) {
    for item in items.items where !item.isSeparatorItem {
        let here = path + [item.title]
        menu.append([
            "path": here,
            "selector": item.action.map { NSStringFromSelector($0) as Any } ?? NSNull(),
            "submenu": item.submenu != nil,
        ])
        if let sub = item.submenu { walk(sub, here) }
    }
}
guard let mainMenu = NSApp.mainMenu else { fail("no main menu after willFinishLaunching") }
walk(mainMenu, [])

// MARK: - The fixture: a media clip with picture and sound, a text clip, a shape clip

let second: Ticks = 600_000
guard var project = ReelProject.new(width: 1920, height: 1080, fps: .thirty) else {
    fail("ReelProject.new answered nil")
}
func apply(_ op: ReelOp) {
    do {
        guard case .applied(let next) = try project.applying(op) else {
            fail("\(op.name) did not apply")
        }
        project = next
    } catch {
        fail("\(op.name): \(error)")
    }
}
guard let track = project.snapshot.tracks.first?.id else { fail("the new project has no track") }
apply(.addMedia(descriptor: MediaDescriptor(
    path: "/nonexistent/tutorial-probe.mov", kind: .video, duration: 4 * second, width: 1920,
    height: 1080, fps: .thirty, hasVideo: true, hasAudio: true)))
guard let media = project.snapshot.media.first?.id else { fail("add_media added nothing") }
